import { useState } from "react";
import type { ReactNode } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface TreeNode {
  id: string;
  label: string;
  children?: TreeNode[];
  icon?: ReactNode;
}

export interface TreeViewProps extends Omit<ViewProps, "children"> {
  nodes: TreeNode[];
  defaultExpandedIds?: string[];
  expandedIds?: string[];
  onExpandedChange?: (expandedIds: string[]) => void;
  onSelect?: (node: TreeNode) => void;
  /** Extend the inner, named parts of the tree: row, rowText or chevron. The React Native counterpart of `classNames`. */
  styles?: {
    row?: StyleProp<ViewStyle>;
    rowText?: StyleProp<TextStyle>;
    chevron?: StyleProp<TextStyle>;
  };
}

export function TreeView({ nodes, defaultExpandedIds = [], expandedIds, onExpandedChange, onSelect, style, styles: parts, ...props }: TreeViewProps) {
  const tokens = useTokens();
  const [internal, setInternal] = useState(defaultExpandedIds);
  const [selected, setSelected] = useState<string>();
  const expanded = expandedIds ?? internal;

  function toggle(id: string) {
    const next = expanded.includes(id) ? expanded.filter((entry) => entry !== id) : [...expanded, id];
    if (expandedIds === undefined) setInternal(next);
    onExpandedChange?.(next);
  }

  function render(list: TreeNode[], depth: number): ReactNode {
    return list.map((node) => {
      const branch = Boolean(node.children?.length);
      const open = expanded.includes(node.id);
      return (
        <View key={node.id}>
          <Pressable
            accessibilityRole="button"
            accessibilityState={{ expanded: branch ? open : undefined, selected: selected === node.id }}
            onPress={() => {
              setSelected(node.id);
              if (branch) toggle(node.id);
              onSelect?.(node);
            }}
            style={({ pressed }) => [
              local.row,
              { paddingLeft: 8 + depth * 16, backgroundColor: selected === node.id || pressed ? tokens.surfaceMuted : "transparent" },
              parts?.row,
            ]}
          >
            <Text style={[{ width: 14, color: tokens.textMuted, fontSize: 14, transform: [{ rotate: open ? "90deg" : "0deg" }] }, parts?.chevron]}>{branch ? "›" : ""}</Text>
            {node.icon}
            <Text style={[{ color: tokens.foreground, fontSize: metrics.text.sm }, parts?.rowText]}>{node.label}</Text>
          </Pressable>
          {branch && open ? render(node.children!, depth + 1) : null}
        </View>
      );
    });
  }

  return (
    <View {...props} accessibilityRole="list" style={[{ alignSelf: "stretch" }, style]}>
      {render(nodes, 0)}
    </View>
  );
}

const local = StyleSheet.create({
  row: { flexDirection: "row", alignItems: "center", gap: 6, minHeight: 36, paddingRight: 8, borderRadius: metrics.radiusControl - 6 },
});

export default TreeView;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
